import{z as l,x as A,o as t,c as p,q as r,j as s,D as e,d as n,s as E,S as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"流水线五级","description":"","frontmatter":{"title":"流水线五级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-five-stage.md","filePath":"cs/pipeline-five-stage.md","lastUpdated":1791063341000}'),d={name:"cs/pipeline-five-stage.md"};function B(c,a,h,C,_,m){const i=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="流水线五级" tabindex="-1">流水线五级 <a class="header-anchor" href="#流水线五级" aria-label="Permalink to &quot;流水线五级&quot;">​</a></h1><div class="epigraph"><p>把一条指令切成可重叠的几段，时钟只需覆盖最慢的一段，吞吐才不再被整条组合路径绑架。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/isa-abi-boundary">上一课</a>把 ISA 钉成硬件合同、ABI 钉成软件互调合同：同一 ISA 可带多份 ABI，扩展集写进目标三元组。<a href="/cs/single-cycle-datapath">单周期数据通路</a>已经能在一个时钟里跑完一条 RISC-V 整数指令，<a href="/cs/multicycle-microcode">多周期与微程序直觉</a>已经承认可以把取指、译码、执行拆开。本课不重画 ALU，也不从「处理器是什么」另起。缺口是：单周期的时钟被最长路径钉死；多周期解放了周期，却把功能单元闲置。本课只把通路切成五级并重叠。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单周期里，取指令存储器、寄存器堆、ALU、数据存储器必须在同一拍内稳定。时钟周期等于这条最长组合路径，简单的 <code>addi</code> 也得等 load 走完。<span class="marginnote">用数字感受一下：教科书里常给的量级是——取指约 200 皮秒、读寄存器堆 100 皮秒、ALU 200 皮秒、访存再 200 皮秒，串成一条路径后单周期时钟至少要约 700 皮秒一拍。切成五级后，最慢的一级也只有两百皮秒左右，同一套电路的时钟频率就能提高数倍。快的不算加法本身，快的是「一拍能启动多少条」。</span>多周期让不同指令占用不同拍，平均 CPI 大于 1，吞吐上不去。缺口不是新的 ISA，而是<strong>同时让多条指令分别占用通路的不同段</strong>。</p><p>RISC-V 整数指令可以切成取指、译码/读寄存器、执行/有效地址、访存、写回。本课只钉这五级；冒险、转发、分支预测都是后课留下的缺口。</p><p><span class="marginnote">经典五级是 COD 教学机的骨架，不是当代乱序核的流水线深度。后课超标量会加宽，本课先把重叠说清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在相邻级之间插入流水线寄存器，锁存本级要交给下级的 PC、指令字、操作数、ALU 结果和控制信号。理想情况下每个时钟推进一级：第五拍起，每拍提交一条指令，吞吐接近每拍一条，而单条指令的延迟仍是五拍。<span class="marginnote">可以类比洗衣服：洗衣机、烘干机、折叠台就是三个「级」。第一批洗完后，第二批进洗衣机的同时第一批进烘干机——设备不再闲置。从投入第一缸衣服到全部叠好，一批的时间没变短，但稳态下每 40 分钟就有一批完成。流水线加速的是「单位时间完成多少」，不是「单件多快」。</span></p>',9)),(t(),s(o,null,{default:e(()=>[E(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20IF%5B%22IF%20%E5%8F%96%E6%8C%87%22%5D%20--%3E%20ID%5B%22ID%20%E8%AF%91%E7%A0%81%22%5D%0A%20%20ID%20--%3E%20EX%5B%22EX%20%E6%89%A7%E8%A1%8C%22%5D%0A%20%20EX%20--%3E%20MEM%5B%22MEM%20%E8%AE%BF%E5%AD%98%22%5D%0A%20%20MEM%20--%3E%20WB%5B%22WB%20%E5%86%99%E5%9B%9E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p>控制仍来自<a href="/cs/control-truth-table">控制器真值表</a>，只是信号随指令在寄存器里向后传，而不是在一拍里驱动整条通路。本课假定指令存储器与数据存储器暂时可同时访问；做不到时就是后面<a href="/cs/structural-hazard">结构冒险</a>一课的缺口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>重叠改变的是利用率，不是指令语义。程序员仍看见顺序 ISA：<a href="/cs/register-file">寄存器堆</a>的写回发生在 WB，读发生在 ID。理想 CPI 从单周期的 1 变成「渐近 1」，时钟频率却可以按级内延迟提高。加速来自吞吐，不来自把加法算得更快。<span class="marginnote">常见误区：以为流水线让每条指令算得更快了。实际单条指令从取指到写回的总延迟不降反略升——级间寄存器的锁存要花时间；变快的是「每秒完成多少条」。另一个易错点：流水线满载时五条指令同时在通路里，一条出了错，后面四条都还不能提交，「谁的异常」由此成为后课的难题。</span></p>',3)),(t(),s(o,null,{default:e(()=>[E(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20S5%5B%22%E7%AC%AC%E4%BA%94%E6%8B%8D%EF%BC%9A%E4%BA%94%E6%9D%A1%E6%8C%87%E4%BB%A4%E5%90%8C%E6%97%B6%E5%8D%A0%E7%9D%80%E4%BA%94%E7%BA%A7%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20I1%5B%22%E6%8C%87%E4%BB%A41%3A%20WB%20%E5%86%99%E5%9B%9E%22%5D%20--%3E%20I2%5B%22%E6%8C%87%E4%BB%A42%3A%20MEM%20%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20I3%5B%22%E6%8C%87%E4%BB%A43%3A%20EX%20%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20I4%5B%22%E6%8C%87%E4%BB%A44%3A%20ID%20%E8%AF%91%E7%A0%81%22%5D%20--%3E%20I5%5B%22%E6%8C%87%E4%BB%A45%3A%20IF%20%E5%8F%96%E6%8C%87%22%5D%0A%20%20end%0A%20%20S5%20--%3E%20OUT%5B%22%E6%9C%AC%E6%8B%8D%E7%BB%93%E6%9D%9F%EF%BC%9A%E6%8C%87%E4%BB%A41%20%E9%80%80%E5%87%BA%E6%B5%81%E6%B0%B4%E7%BA%BF%EF%BC%8C%E6%8C%87%E4%BB%A46%20%E4%BB%8E%20IF%20%E8%BF%9B%E5%85%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p>五级是对 RISC-V 整数核的划分：load/store 需要 MEM，算术指令在 EX 已出结果，分支的目标与条件也在 EX 才齐。划分本身会制造后课要处理的相关：后指令在 ID 读寄存器时，前指令可能还没写回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入停顿、转发或分支预测，也不处理浮点或多周期运算。异常在<a href="/cs/exception-interrupt-entry">异常与中断入口</a>已有入口约定，流水线里同时有多条指令时「哪一条的 PC 算异常」是<a href="/cs/pipeline-exception">流水线异常</a>的缺口。特权级规则不变：流水线不额外授权。</p><p>后课默认：谈到经典流水线，指 IF/ID/EX/MEM/WB 与级间寄存器。理想吞吐每拍一条，尚未计入冒险。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单周期被最长路径卡住；五级重叠把时钟收到最慢的一段。</li><li>理想情况下第五拍起每拍完成一条，CPI 渐近为 1。</li><li>冒险、转发、异常精确性都是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>Computer Organization and Design</em> RISC-V 版流水线章。</li></ul>',6))])}const f=l(d,[["render",B]]);export{D as __pageData,f as default};
